/**
 * Number extraction + normalisation shared by the fact checker and publishing
 * guards. "₹1,200 cr", "1200 crore" and "₹1,200 करोड़" all normalise to
 * { value: 1200, scale: "crore" }; Devanagari digits are converted first.
 */

export type NumberScale =
  | "thousand"
  | "lakh"
  | "million"
  | "crore"
  | "billion"
  | "trillion"
  | "percent";

export type NumberToken = {
  raw: string;
  value: number;
  scale: NumberScale | null;
};

const SCALE_ALIASES: Record<string, NumberScale> = {
  k: "thousand",
  thousand: "thousand",
  "हज़ार": "thousand",
  "हजार": "thousand",
  lakh: "lakh",
  lakhs: "lakh",
  lac: "lakh",
  "लाख": "lakh",
  mn: "million",
  million: "million",
  millions: "million",
  cr: "crore",
  "cr.": "crore",
  crore: "crore",
  crores: "crore",
  "करोड़": "crore",
  "करोड": "crore",
  bn: "billion",
  billion: "billion",
  billions: "billion",
  "अरब": "billion",
  tn: "trillion",
  trillion: "trillion",
  "%": "percent",
  percent: "percent",
  "per cent": "percent",
  "प्रतिशत": "percent",
  "फीसदी": "percent",
  "फ़ीसदी": "percent",
};

const SCALE_MULTIPLIER: Partial<Record<NumberScale, number>> = {
  thousand: 1e3,
  lakh: 1e5,
  million: 1e6,
  crore: 1e7,
  billion: 1e9,
  trillion: 1e12,
};

const DEVANAGARI_DIGITS = "०१२३४५६७८९";

export function toAsciiDigits(text: string): string {
  return text.replace(/[०-९]/g, (d) => String(DEVANAGARI_DIGITS.indexOf(d)));
}

// Latin scale words must end at a word boundary ("5 km" is not "5 k").
const NUMBER_PATTERN =
  /(\d+(?:,\d+)*(?:\.\d+)?)(?:\s*(%|per cent|percent|crores?|cr\.?(?![a-z])|lakhs?(?![a-z])|lac(?![a-z])|millions?|mn(?![a-z])|billions?|bn(?![a-z])|trillion|tn(?![a-z])|thousand|k(?![a-z])|करोड़|करोड|लाख|अरब|हज़ार|हजार|प्रतिशत|फ़ीसदी|फीसदी))?/gi;

export function extractNumbers(text: string): NumberToken[] {
  const ascii = toAsciiDigits(text);
  const tokens: NumberToken[] = [];
  for (const match of ascii.matchAll(NUMBER_PATTERN)) {
    // Skip digits glued to letters (e.g. "Q3", "G20", "4G") — labels, not quantities.
    const start = match.index ?? 0;
    const before = ascii[start - 1];
    if (before && /[A-Za-z]/.test(before)) {
      continue;
    }
    const value = Number(match[1].replace(/,/g, ""));
    if (!Number.isFinite(value)) {
      continue;
    }
    const scaleWord = match[2]?.toLowerCase();
    tokens.push({
      raw: match[0].trim(),
      value,
      scale: scaleWord ? (SCALE_ALIASES[scaleWord] ?? null) : null,
    });
  }
  return tokens;
}

function absoluteValue(token: NumberToken): number | null {
  if (!token.scale || token.scale === "percent") {
    return null;
  }
  const multiplier = SCALE_MULTIPLIER[token.scale];
  return multiplier ? token.value * multiplier : null;
}

function nearlyEqual(a: number, b: number): boolean {
  return Math.abs(a - b) <= Math.max(1e-9, Math.abs(a) * 1e-9);
}

/** Same value (and compatible scale), or same absolute amount (120 bn = 12,000 cr). */
export function numbersMatch(script: NumberToken, fact: NumberToken): boolean {
  if (nearlyEqual(script.value, fact.value)) {
    return (
      script.scale == null || fact.scale == null || script.scale === fact.scale
    );
  }
  const a = absoluteValue(script);
  const b = absoluteValue(fact);
  return a != null && b != null && nearlyEqual(a, b);
}

/** Numbers in `text` that match nothing in `allowed`. */
export function unsupportedNumbers(
  text: string,
  allowed: NumberToken[],
): NumberToken[] {
  return extractNumbers(text).filter(
    (token) => !allowed.some((fact) => numbersMatch(token, fact)),
  );
}

/** Splits on . ! ? and the Devanagari danda, keeping the punctuation. */
export function splitSentences(text: string): string[] {
  return text
    .split(/(?<=[.!?।])\s+/)
    .map((sentence) => sentence.trim())
    .filter(Boolean);
}

/** Whitespace word count (works for Devanagari too). */
export function countWords(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import {
  countWords,
  extractNumbers,
  numbersMatch,
  splitSentences,
  unsupportedNumbers,
} from "./numbers";

describe("extractNumbers", () => {
  it("normalises currency, separators and Indian scales", () => {
    const [a] = extractNumbers("₹1,200 cr");
    const [b] = extractNumbers("1200 crore");
    const [c] = extractNumbers("₹१,२०० करोड़");
    for (const token of [a, b, c]) {
      assert.equal(token.value, 1200);
      assert.equal(token.scale, "crore");
    }
  });

  it("reads percents in English and Hindi", () => {
    assert.equal(extractNumbers("up 4.5%")[0].scale, "percent");
    assert.equal(extractNumbers("4.5 प्रतिशत")[0].scale, "percent");
    assert.equal(extractNumbers("4.5 per cent")[0].scale, "percent");
  });

  it("does not treat units or labels as scales/quantities", () => {
    assert.deepEqual(
      extractNumbers("5 km away").map((t) => [t.value, t.scale]),
      [[5, null]],
    );
    assert.deepEqual(extractNumbers("Q3 results and G20"), []);
  });
});

describe("numbersMatch", () => {
  it("matches equal values with compatible scales", () => {
    const [script] = extractNumbers("1,200");
    const [fact] = extractNumbers("₹1,200 crore");
    assert.equal(numbersMatch(script, fact), true);
    assert.equal(
      numbersMatch(extractNumbers("1200 lakh")[0], fact),
      false,
    );
  });

  it("matches the same amount across scales", () => {
    assert.equal(
      numbersMatch(extractNumbers("120 billion")[0], extractNumbers("12,000 crore")[0]),
      true,
    );
  });
});

describe("unsupportedNumbers", () => {
  it("flags numbers absent from the allowed list", () => {
    const allowed = extractNumbers("Revenue rose 12% to ₹3,400 crore in 2025.");
    assert.deepEqual(
      unsupportedNumbers("Revenue hit 3,400 crore, up 15%.", allowed).map((t) => t.raw),
      ["15%"],
    );
  });
});

describe("text helpers", () => {
  it("splits English and Hindi sentences and counts words", () => {
    assert.deepEqual(splitSentences("One. Two? तीन। चार"), ["One.", "Two?", "तीन।", "चार"]);
    assert.equal(countWords("  यह एक  वाक्य है "), 4);
  });
});

