/**
 * Pexels photo + video search (https://www.pexels.com/api/documentation/).
 * Optional: callers check `isPexelsConfigured()` and skip when no key is set.
 */

import { z } from "zod";
import { tool } from "@/lib/observability";

const PEXELS_API_BASE = "https://api.pexels.com/v1";

const pexelsPhotoSchema = z.looseObject({
  id: z.number(),
  url: z.string(),
  alt: z.string().nullish(),
  photographer: z.string().nullish(),
  width: z.number().nullish(),
  height: z.number().nullish(),
  src: z.looseObject({
    original: z.string(),
    large: z.string().nullish(),
    medium: z.string().nullish(),
  }),
});

const pexelsVideoFileSchema = z.looseObject({
  quality: z.string().nullish(),
  file_type: z.string().nullish(),
  width: z.number().nullish(),
  height: z.number().nullish(),
  link: z.string(),
});

const pexelsVideoSchema = z.looseObject({
  id: z.number(),
  url: z.string(),
  image: z.string().nullish(),
  duration: z.number().nullish(),
  width: z.number().nullish(),
  height: z.number().nullish(),
  video_files: z.array(pexelsVideoFileSchema).default([]),
});

const photoSearchResponseSchema = z.looseObject({
  photos: z.array(pexelsPhotoSchema).default([]),
});

const videoSearchResponseSchema = z.looseObject({
  videos: z.array(pexelsVideoSchema).default([]),
});

export type PexelsPhoto = z.infer<typeof pexelsPhotoSchema>;
export type PexelsVideo = z.infer<typeof pexelsVideoSchema>;

export type PexelsSearchParams = {
  query: string;
  orientation?: "landscape" | "portrait" | "square";
  perPage?: number;
};

export function isPexelsConfigured(): boolean {
  return Boolean(process.env.PEXELS_API_KEY?.trim());
}

async function pexelsGet(path: string, params: PexelsSearchParams) {
  const apiKey = process.env.PEXELS_API_KEY?.trim();
  if (!apiKey) {
    throw new Error("PEXELS_API_KEY is not set");
  }
  const url = new URL(`${PEXELS_API_BASE}${path}`);
  url.searchParams.set("query", params.query);
  url.searchParams.set("per_page", String(params.perPage ?? 6));
  if (params.orientation) {
    url.searchParams.set("orientation", params.orientation);
  }
  const response = await fetch(url, {
    headers: { Authorization: apiKey },
    signal: AbortSignal.timeout(20_000),
  });
  if (!response.ok) {
    throw new Error(`Pexels ${path} failed with HTTP ${response.status}`);
  }
  return response.json() as Promise<unknown>;
}

async function searchPhotos(params: PexelsSearchParams): Promise<PexelsPhoto[]> {
  const json = await pexelsGet("/search", params);
  return photoSearchResponseSchema.parse(json).photos;
}

async function searchVideos(params: PexelsSearchParams): Promise<PexelsVideo[]> {
  const json = await pexelsGet("/videos/search", params);
  return videoSearchResponseSchema.parse(json).videos;
}

export const pexelsClient = {
  searchPhotos: tool("pexels.searchPhotos", searchPhotos),
  searchVideos: tool("pexels.searchVideos", searchVideos),
};

/**
 * External calls for the video script pipeline. Every call goes through
 * `callTool` (cache, retries, per-run budget) and returns `null` / `[]` on failure.
 *
 * SerpApi engines and fields follow the docs:
 * - google_news: news_results[].{title, link, source.name, date, iso_date}
 * - google_images / google_images_light: images_results[].{title, link, original, thumbnail, source}
 * - bing_images: images_results[].{title, link, original, thumbnail, source, domain}
 */

import { callTool, type CallBudget } from "@/clients/callTool";
import {
  isPexelsConfigured,
  pexelsClient,
  type PexelsSearchParams,
} from "@/clients/pexelsClient";
import { z } from "zod";

const DAY_MS = 24 * 60 * 60 * 1000;
export const SCRAPE_CACHE_TTL_MS = 7 * DAY_MS;
export const NEWS_SEARCH_CACHE_TTL_MS = 6 * 60 * 60 * 1000;
export const IMAGE_SEARCH_CACHE_TTL_MS = 7 * DAY_MS;

export type NewsHit = {
  url: string;
  title: string;
  source: string | null;
  isoDate: string | null;
};

export type ImageEngine = "google_images" | "google_images_light" | "bing_images";

export type ImageHit = {
  source: ImageEngine | "pexels";
  url: string;
  previewUrl: string | null;
  pageUrl: string | null;
  title: string | null;
  site: string | null;
  width: number | null;
  height: number | null;
};

export type VideoHit = {
  source: "pexels";
  url: string;
  previewUrl: string | null;
  pageUrl: string;
  title: string | null;
  durationSec: number | null;
};

export type VideoTools = {
  scrapeMarkdown(url: string, budget: CallBudget): Promise<string | null>;
  searchNews(
    query: { q: string; sortByDate: boolean },
    budget: CallBudget,
  ): Promise<NewsHit[]>;
  searchImages(
    engine: ImageEngine,
    q: string,
    budget: CallBudget,
  ): Promise<ImageHit[]>;
  /** Empty when `PEXELS_API_KEY` is not set. */
  searchPexelsPhotos(q: string, orientation: PexelsSearchParams["orientation"], budget: CallBudget): Promise<ImageHit[]>;
  searchPexelsVideos(q: string, orientation: PexelsSearchParams["orientation"], budget: CallBudget): Promise<VideoHit[]>;
  pexelsEnabled(): boolean;
};

const httpUrl = z
  .string()
  .refine((value) => /^https?:\/\//i.test(value), "not an http(s) url");

const newsItemSchema = z.looseObject({
  link: httpUrl,
  title: z.string().min(1),
  source: z.looseObject({ name: z.string().nullish() }).nullish(),
  iso_date: z.string().nullish(),
});

const imageItemSchema = z.looseObject({
  original: httpUrl,
  thumbnail: z.string().nullish(),
  link: z.string().nullish(),
  title: z.string().nullish(),
  source: z.string().nullish(),
  domain: z.string().nullish(),
  original_width: z.number().nullish(),
  original_height: z.number().nullish(),
});

function parseList<T>(value: unknown, schema: z.ZodType<T>): T[] {
  if (!Array.isArray(value)) {
    return [];
  }
  const rows: T[] = [];
  for (const row of value) {
    const parsed = schema.safeParse(row);
    if (parsed.success) {
      rows.push(parsed.data);
    }
  }
  return rows;
}

async function serpSearch(params: Record<string, unknown>) {
  const { serpClient } = await import("@/clients/serpCleint");
  return serpClient.search(params);
}

/** SerpApi returns 200 with an `error` field for some failures. */
function serpHasError(value: unknown): boolean {
  return Boolean(
    value &&
      typeof value === "object" &&
      typeof (value as { error?: unknown }).error === "string" &&
      !/hasn't returned any results/i.test((value as { error: string }).error),
  );
}

export const defaultVideoTools: VideoTools = {
  async scrapeMarkdown(url, budget) {
    const result = await callTool({
      tool: "firecrawl.scrape",
      params: { url },
      ttlMs: SCRAPE_CACHE_TTL_MS,
      budget,
      run: async () => {
        const { firecrawlClient } = await import("@/clients/FireCrawlClient");
        const { scrapeMarkdownFromFirecrawl } = await import(
          "@/services/chat/chatSerpResearch"
        );
        const scraped = await firecrawlClient.scrape({ url });
        return { markdown: scrapeMarkdownFromFirecrawl(scraped) };
      },
    });
    return result?.markdown ?? null;
  },

  async searchNews(query, budget) {
    const params = {
      engine: "google_news",
      q: query.q,
      gl: "in",
      hl: "en",
      ...(query.sortByDate ? { so: 1 } : {}),
    };
    const json = await callTool({
      tool: "serp.google_news",
      params,
      ttlMs: NEWS_SEARCH_CACHE_TTL_MS,
      budget,
      run: () => serpSearch(params),
      isFailure: serpHasError,
    });
    const items = parseList(
      (json as { news_results?: unknown } | null)?.news_results,
      newsItemSchema,
    );
    return items.map((item) => ({
      url: item.link,
      title: item.title,
      source: item.source?.name ?? null,
      isoDate: item.iso_date ?? null,
    }));
  },

  async searchImages(engine, q, budget) {
    const params =
      engine === "bing_images"
        ? { engine, q, cc: "in" }
        : { engine, q, gl: "in", hl: "en" };
    const json = await callTool({
      tool: `serp.${engine}`,
      params,
      ttlMs: IMAGE_SEARCH_CACHE_TTL_MS,
      budget,
      run: () => serpSearch(params),
      isFailure: serpHasError,
    });
    const items = parseList(
      (json as { images_results?: unknown } | null)?.images_results,
      imageItemSchema,
    );
    return items.map((item) => ({
      source: engine,
      url: item.original,
      previewUrl: item.thumbnail ?? null,
      pageUrl: item.link ?? null,
      title: item.title ?? null,
      site: item.source ?? item.domain ?? null,
      width: item.original_width ?? null,
      height: item.original_height ?? null,
    }));
  },

  async searchPexelsPhotos(q, orientation, budget) {
    if (!isPexelsConfigured()) {
      return [];
    }
    const photos = await callTool({
      tool: "pexels.photos",
      params: { q, orientation },
      ttlMs: IMAGE_SEARCH_CACHE_TTL_MS,
      budget,
      run: () => pexelsClient.searchPhotos({ query: q, orientation, perPage: 6 }),
    });
    return (photos ?? []).map((photo) => ({
      source: "pexels" as const,
      url: photo.src.original,
      previewUrl: photo.src.medium ?? photo.src.large ?? null,
      pageUrl: photo.url,
      title: photo.alt ?? null,
      site: photo.photographer ? `Pexels / ${photo.photographer}` : "Pexels",
      width: photo.width ?? null,
      height: photo.height ?? null,
    }));
  },

  async searchPexelsVideos(q, orientation, budget) {
    if (!isPexelsConfigured()) {
      return [];
    }
    const videos = await callTool({
      tool: "pexels.videos",
      params: { q, orientation },
      ttlMs: IMAGE_SEARCH_CACHE_TTL_MS,
      budget,
      run: () => pexelsClient.searchVideos({ query: q, orientation, perPage: 6 }),
    });
    const hits: VideoHit[] = [];
    for (const video of videos ?? []) {
      // Prefer an HD mp4 over 4K originals to keep files manageable.
      const file =
        video.video_files.find((f) => f.quality === "hd" && f.file_type === "video/mp4") ??
        video.video_files[0];
      if (!file) {
        continue;
      }
      hits.push({
        source: "pexels",
        url: file.link,
        previewUrl: video.image ?? null,
        pageUrl: video.url,
        title: null,
        durationSec: video.duration ?? null,
      });
    }
    return hits;
  },

  pexelsEnabled: isPexelsConfigured,
};

import { z } from "zod";

export const researchSourceInputSchema = z.object({
  id: z.string().min(1),
  url: z.string().min(1),
  title: z.string(),
  domain: z.string().nullable(),
  scrapedContent: z.string().nullable(),
  transcript: z.string().nullable(),
  publishedAt: z.string().nullable(),
});

export const researchBuilderInputSchema = z.object({
  story: z.object({
    id: z.string().min(1),
    title: z.string().min(1),
    description: z.string().nullable(),
    summary: z.string(),
    content: z.string(),
    category: z.string(),
    location: z.string().nullable(),
    publishedAt: z.string().nullable(),
    createdAt: z.string(),
  }),
  sources: z.array(researchSourceInputSchema),
  /** ISO timestamp; injected so age checks are deterministic. */
  now: z.string(),
});

export type ResearchBuilderInput = z.input<typeof researchBuilderInputSchema>;

export const FACT_TYPES = ["number", "date", "name", "event", "quote", "context"] as const;

export const factSchema = z.object({
  id: z.string().min(1),
  text: z.string().min(1),
  type: z.enum(FACT_TYPES),
  value: z.string().optional(),
  /** Quotes only. */
  speaker: z.string().optional(),
  sourceIds: z.array(z.string()).min(1),
  sourceUrls: z.array(z.string()),
  confidence: z.enum(["high", "medium"]),
});

export const factSheetSourceSchema = z.object({
  id: z.string(),
  url: z.string(),
  title: z.string(),
  /** stored = existing NewsSource / story; search = found by this run. */
  origin: z.enum(["story", "stored", "search"]),
});

export const factSheetSchema = z.object({
  facts: z.array(factSchema).min(1),
  whatHappened: z.string().min(1),
  whatChanged: z.string(),
  whyItMatters: z.array(z.string()),
  whoIsAffected: z.array(z.string()),
  openQuestions: z.array(z.string()),
  conflicts: z.array(
    z.object({ factA: z.string(), factB: z.string(), note: z.string() }),
  ),
  /** Finance / markets story → scripts and descriptions carry the disclaimer. */
  isFinance: z.boolean(),
  sources: z.array(factSheetSourceSchema),
  searchQueries: z.array(z.string()),
});

export type Fact = z.infer<typeof factSchema>;
export type FactSheet = z.infer<typeof factSheetSchema>;

/** LLM output: strict-mode friendly (nullable, no string length limits). */
export const factExtractionSchema = z.object({
  facts: z
    .array(
      z.object({
        text: z.string(),
        type: z.enum(FACT_TYPES),
        value: z.string().nullable(),
        speaker: z.string().nullable(),
        sourceIds: z.array(z.string()),
        confidence: z.enum(["high", "medium"]),
      }),
    )
    .max(60),
  whatHappened: z.string(),
  whatChanged: z.string(),
  whyItMatters: z.array(z.string()).max(6),
  whoIsAffected: z.array(z.string()).max(6),
  openQuestions: z.array(z.string()).max(6),
  conflicts: z
    .array(
      z.object({
        factA: z.number().int(),
        factB: z.number().int(),
        note: z.string(),
      }),
    )
    .max(10),
  isFinance: z.boolean(),
});

export type FactExtraction = z.infer<typeof factExtractionSchema>;

/**
 * researchBuilder — builds the FactSheet every later video agent relies on.
 *
 * 1. Stored source texts; missing full text fetched with Firecrawl (≤ 5 pages, cached).
 * 2. Fewer than 2 usable sources OR story older than 48h → 1–2 Google News
 *    searches, ≤ 3 new pages fetched (kept on the FactSheet as `search` sources).
 * 3. LLM extracts facts from those texts only, then a grounding pass drops any
 *    fact whose numbers or verbatim quote do not appear in its cited sources.
 */

import { createCallBudget, type CallBudget } from "@/clients/callTool";
import { runVideoAgent, type AgentResult } from "@/Agents/video/shared/agentResult";
import {
  defaultVideoGenerate,
  resolveVideoModel,
  type VideoGenerate,
} from "@/Agents/video/shared/llm";
import { extractNumbers, unsupportedNumbers } from "@/Agents/video/shared/numbers";
import { defaultVideoTools, type VideoTools } from "@/services/videoScript/videoTools";
import { PROMPT_VERSION, RESEARCH_BUILDER_SYSTEM_PROMPT } from "./prompt";
import {
  factExtractionSchema,
  factSheetSchema,
  researchBuilderInputSchema,
  type Fact,
  type FactExtraction,
  type FactSheet,
  type ResearchBuilderInput,
} from "./schema";

export { PROMPT_VERSION };
export * from "./schema";

export const MIN_USABLE_SOURCE_CHARS = 400;
export const MAX_STORED_SCRAPES = 5;
export const MAX_SEARCH_PAGES = 3;
export const STALE_STORY_HOURS = 48;
const MAX_CHARS_PER_SOURCE = 8_000;
const FINANCE_CATEGORY = /business|financ|market|econom|stock|bank|crypto|invest/i;

export type ResearchBuilderDeps = {
  generate?: VideoGenerate;
  tools?: VideoTools;
  /** External calls allowed for this run (scrapes + searches). */
  budget?: CallBudget;
  model?: string;
};

type WorkingSource = {
  id: string;
  url: string;
  title: string;
  text: string | null;
  origin: "story" | "stored" | "search";
};

function isUsable(text: string | null | undefined): text is string {
  return Boolean(text && text.trim().length >= MIN_USABLE_SOURCE_CHARS);
}

function isHttpUrl(url: string): boolean {
  return /^https?:\/\//i.test(url);
}

function normaliseForQuote(text: string): string {
  return text
    .toLowerCase()
    .replace(/[“”„"]/g, '"')
    .replace(/[‘’']/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function storyAgeHours(input: { publishedAt: string | null; createdAt: string }, now: string) {
  const reference = Date.parse(input.publishedAt ?? input.createdAt);
  const current = Date.parse(now);
  if (!Number.isFinite(reference) || !Number.isFinite(current)) {
    return 0;
  }
  return (current - reference) / 3_600_000;
}

async function collectSources(
  input: ReturnType<typeof researchBuilderInputSchema.parse>,
  tools: VideoTools,
  budget: CallBudget,
): Promise<{ sources: WorkingSource[]; searchQueries: string[] }> {
  const stored: WorkingSource[] = input.sources.map((source) => ({
    id: source.id,
    url: source.url,
    title: source.title,
    text: isUsable(source.scrapedContent)
      ? source.scrapedContent
      : isUsable(source.transcript)
        ? source.transcript
        : null,
    origin: "stored",
  }));

  const missing = stored
    .filter((source) => !source.text && isHttpUrl(source.url))
    .slice(0, MAX_STORED_SCRAPES);
  await Promise.all(
    missing.map(async (source) => {
      const markdown = await tools.scrapeMarkdown(source.url, budget);
      if (isUsable(markdown)) {
        source.text = markdown;
      }
    }),
  );

  const usableCount = stored.filter((source) => source.text).length;
  const searchQueries: string[] = [];
  const found: WorkingSource[] = [];
  const ageHours = storyAgeHours(input.story, input.now);

  if (usableCount < 2 || ageHours > STALE_STORY_HOURS) {
    const queries = [{ q: input.story.title, sortByDate: true }];
    if (usableCount < 2) {
      queries.push({ q: input.story.title, sortByDate: false });
    }
    const known = new Set(stored.map((source) => source.url));
    const hits = (
      await Promise.all(
        queries.map((query) => {
          searchQueries.push(`${query.q}${query.sortByDate ? " (latest)" : ""}`);
          return tools.searchNews(query, budget);
        }),
      )
    ).flat();

    const fresh = hits
      .filter((hit, index) => !known.has(hit.url) && hits.findIndex((h) => h.url === hit.url) === index)
      .sort((a, b) => (Date.parse(b.isoDate ?? "") || 0) - (Date.parse(a.isoDate ?? "") || 0))
      .slice(0, MAX_SEARCH_PAGES);

    const scraped = await Promise.all(
      fresh.map(async (hit) => ({ hit, markdown: await tools.scrapeMarkdown(hit.url, budget) })),
    );
    scraped.forEach(({ hit, markdown }, index) => {
      if (isUsable(markdown)) {
        found.push({
          id: `search-${index + 1}`,
          url: hit.url,
          title: hit.title,
          text: markdown,
          origin: "search",
        });
      }
    });
  }

  const storyText = [
    input.story.title,
    input.story.description,
    input.story.summary,
    input.story.content,
  ]
    .filter(Boolean)
    .join("\n\n");

  return {
    sources: [
      {
        id: "story",
        url: `/newsStory/${input.story.id}`,
        title: input.story.title,
        text: storyText,
        origin: "story",
      },
      ...stored,
      ...found,
    ],
    searchQueries,
  };
}

/**
 * Keeps only facts grounded in their cited texts: every number must appear in
 * a cited source and every quote must be verbatim. Re-numbers ids F1…Fn.
 */
export function groundFacts(
  extraction: FactExtraction,
  sources: Array<{ id: string; url: string; text: string | null; origin: string }>,
): { facts: Fact[]; conflicts: FactSheet["conflicts"] } {
  const byId = new Map(sources.filter((s) => s.text).map((s) => [s.id, s]));
  const keptIdByPosition = new Map<number, string>();
  const facts: Fact[] = [];

  extraction.facts.forEach((raw, index) => {
    const sourceIds = [...new Set(raw.sourceIds)].filter((id) => byId.has(id));
    if (sourceIds.length === 0 || !raw.text.trim()) {
      return;
    }
    const citedText = sourceIds.map((id) => byId.get(id)?.text ?? "").join("\n");

    const claimText = `${raw.text} ${raw.value ?? ""}`;
    if (unsupportedNumbers(claimText, extractNumbers(citedText)).length > 0) {
      return;
    }
    if (raw.type === "quote") {
      if (!raw.value || !normaliseForQuote(citedText).includes(normaliseForQuote(raw.value))) {
        return;
      }
    }

    const id = `F${facts.length + 1}`;
    keptIdByPosition.set(index + 1, id);
    facts.push({
      id,
      text: raw.text.trim(),
      type: raw.type,
      ...(raw.value?.trim() ? { value: raw.value.trim() } : {}),
      ...(raw.type === "quote" && raw.speaker?.trim() ? { speaker: raw.speaker.trim() } : {}),
      sourceIds,
      sourceUrls: sourceIds
        .map((sourceId) => byId.get(sourceId))
        .filter((source) => source && source.origin !== "story")
        .map((source) => source!.url),
      confidence: raw.confidence,
    });
  });

  const conflicts = extraction.conflicts.flatMap((conflict) => {
    const factA = keptIdByPosition.get(conflict.factA);
    const factB = keptIdByPosition.get(conflict.factB);
    return factA && factB && factA !== factB ? [{ factA, factB, note: conflict.note }] : [];
  });

  return { facts, conflicts };
}

export function createResearchBuilder(deps: ResearchBuilderDeps = {}) {
  const generate = deps.generate ?? defaultVideoGenerate;
  const tools = deps.tools ?? defaultVideoTools;

  return async function researchBuilder(
    rawInput: ResearchBuilderInput,
  ): Promise<AgentResult<FactSheet>> {
    return runVideoAgent(
      "researchBuilder",
      { input: researchBuilderInputSchema, output: factSheetSchema },
      rawInput,
      async (input) => {
        const budget = deps.budget ?? createCallBudget(12);
        const { sources, searchQueries } = await collectSources(input, tools, budget);
        const usable = sources.filter((source) => source.text);

        const extraction = await generate({
          model: resolveVideoModel(deps.model),
          system: RESEARCH_BUILDER_SYSTEM_PROMPT,
          prompt: `Build the fact sheet for this story: ${input.story.title}`,
          extraContext: {
            story: {
              category: input.story.category,
              location: input.story.location,
              publishedAt: input.story.publishedAt,
            },
            sources: usable.map((source) => ({
              id: source.id,
              title: source.title,
              url: source.origin === "story" ? null : source.url,
              text: source.text!.slice(0, MAX_CHARS_PER_SOURCE),
            })),
          },
          schemaName: "VideoFactSheet",
          schemaDescription: "Grounded facts extracted from the provided texts only.",
          output: factExtractionSchema,
          temperature: 0,
          maxOutputTokens: 8_000,
        });

        const { facts, conflicts } = groundFacts(extraction, usable);
        if (facts.length === 0) {
          throw new Error("no facts could be grounded in the sources");
        }

        return {
          facts,
          whatHappened: extraction.whatHappened.trim() || input.story.summary,
          whatChanged: extraction.whatChanged.trim(),
          whyItMatters: extraction.whyItMatters,
          whoIsAffected: extraction.whoIsAffected,
          openQuestions: extraction.openQuestions,
          conflicts,
          isFinance: extraction.isFinance || FINANCE_CATEGORY.test(input.story.category),
          sources: usable.map(({ id, url, title, origin }) => ({ id, url, title, origin })),
          searchQueries,
        };
      },
    );
  };
}

export const runResearchBuilder = createResearchBuilder();

