import { factSheetSchema } from "@/Agents/video/researchBuilder/schema";
import { z } from "zod";

export const FINANCE_DISCLAIMER = "For information only, not investment advice.";

export const scriptOptionsSchema = z.object({
  language: z.enum(["hi", "en"]),
  minSec: z.number().int().min(1),
  maxSec: z.number().int().min(1),
  pace: z.enum(["slow", "normal", "fast"]),
  aspectRatio: z.enum(["9:16", "16:9"]),
});

export const scriptWriterInputSchema = z.object({
  factSheet: factSheetSchema,
  story: z.object({ title: z.string(), category: z.string() }),
  options: scriptOptionsSchema,
});

export type ScriptWriterInput = z.input<typeof scriptWriterInputSchema>;
export type ScriptOptions = z.infer<typeof scriptOptionsSchema>;

export const beatSchema = z.object({
  index: z.number().int().min(0),
  startSec: z.number().min(0),
  endSec: z.number().min(0),
  spokenText: z.string().min(1),
  /** ≤ 6 words. */
  onScreenText: z.string().optional(),
  kind: z.enum(["fact", "explain"]),
  factIds: z.array(z.string()),
  priority: z.enum(["core", "optional"]),
  cutNote: z.string().optional(),
});

export const scriptOutputSchema = z.object({
  title: z.string().min(1),
  hookOptions: z.array(z.string()).length(3),
  beats: z.array(beatSchema).min(1),
  cta: z.string(),
  wordCount: z.number().int(),
  estimatedSec: z.number().int(),
  lengthReason: z.string(),
  wordsPerSecond: z.number(),
  /** Present for finance stories. */
  disclaimer: z.string().optional(),
});

export type Beat = z.infer<typeof beatSchema>;
export type ScriptOutput = z.infer<typeof scriptOutputSchema>;

/** LLM output (strict-mode friendly). */
export const scriptDraftSchema = z.object({
  title: z.string(),
  hookOptions: z.array(z.string()).min(3).max(3),
  beats: z
    .array(
      z.object({
        spokenText: z.string(),
        onScreenText: z.string().nullable(),
        kind: z.enum(["fact", "explain"]),
        factIds: z.array(z.string()),
        priority: z.enum(["core", "optional"]),
        cutNote: z.string().nullable(),
      }),
    )
    .min(8)
    .max(18),
  cta: z.string(),
});

export type ScriptDraft = z.infer<typeof scriptDraftSchema>;

/** Bump whenever the system prompt below changes. */
export const PROMPT_VERSION = "v1";

export function buildScriptWriterSystemPrompt(input: {
  language: "hi" | "en";
  targetWordsMin: number;
  targetWordsMax: number;
  hookMaxWords: number;
  ctaMaxWords: number;
  isFinance: boolean;
}): string {
  const languageLine =
    input.language === "hi"
      ? "Write the spoken script in natural, conversational Hindi (Devanagari) as people actually speak it; common English words (company names, 'market', 'app') are fine. Write every number as digits (e.g. ₹1,200 करोड़, 4.5%)."
      : "Write the spoken script in natural, conversational English. Write every number as digits (e.g. ₹1,200 crore, 4.5%).";

  return [
    "You write talking-head news video scripts: one person speaking straight to camera, like a sharp friend explaining the news.",
    languageLine,
    "",
    "FACTS: Use ONLY the facts in the provided fact sheet. Every number, date, name and quote you say must come from a fact,",
    "copied exactly (same number, unit and currency). Never add facts, background, or numbers from your own knowledge.",
    "Do not use any number that is not in the fact sheet — not even counts like \"3 reasons\" or \"in 2 minutes\".",
    "Where sources conflict, say so plainly instead of picking one. No investment advice, predictions or recommendations.",
    input.isFinance ? "This is a finance story: stay neutral and informational." : "",
    "",
    `LENGTH: ${input.targetWordsMin}–${input.targetWordsMax} spoken words in total. Never pad: if the facts are thin, be short.`,
    "",
    "STRUCTURE, 8–18 beats (a beat = 1–3 short spoken sentences, one idea):",
    `1. Hook (first beat, ≤ ${input.hookMaxWords} words): a surprising number, a question, or the consequence for the viewer.`,
    "2. What happened.",
    "3. Key numbers (one number per beat so the editor can animate it).",
    "4. Why it matters / who is affected.",
    "5. What to watch next (use the open questions; no predictions).",
    `6. CTA (last beat, ≤ ${input.ctaMaxWords} words): e.g. follow for more. Its spokenText must equal \`cta\`.`,
    "",
    "Per beat:",
    "- kind: \"fact\" when it states facts (list their ids in factIds), \"explain\" for framing/transitions (factIds may be empty).",
    "- onScreenText: up to 6 words for a caption/callout, or null.",
    "- priority: \"core\" for the beats the story needs; mark extra detail \"optional\" so the creator can cut it, and give a cutNote saying what is lost.",
    "",
    "Also give a short punchy title and exactly 3 alternative hook lines (hookOptions) built from the same facts.",
  ]
    .filter((line) => line !== "")
    .join("\n");
}

/**
 * scriptWriter — turns the FactSheet into a timed, talking-head script.
 *
 * Length comes from content, never padded: thin (≤ 6 strong facts) ~60–75s,
 * normal ~90–120s, rich up to ~140s, all clamped to [minSec, maxSec]. The LLM
 * writes beats; timing, word counts and the soft-limit trim are deterministic.
 */

import { runVideoAgent, type AgentResult } from "@/Agents/video/shared/agentResult";
import {
  defaultVideoGenerate,
  resolveVideoModel,
  type VideoGenerate,
} from "@/Agents/video/shared/llm";
import {
  CTA_MAX_SEC,
  HOOK_MAX_SEC,
  MAX_SEC_TOLERANCE,
  timeBeats,
  totalWords,
  wordsPerSecond,
} from "@/Agents/video/shared/timing";
import type { FactSheet } from "@/Agents/video/researchBuilder/schema";
import { buildScriptWriterSystemPrompt, PROMPT_VERSION } from "./prompt";
import {
  FINANCE_DISCLAIMER,
  scriptDraftSchema,
  scriptOutputSchema,
  scriptWriterInputSchema,
  type Beat,
  type ScriptDraft,
  type ScriptOptions,
  type ScriptOutput,
  type ScriptWriterInput,
} from "./schema";

export { PROMPT_VERSION };
export * from "./schema";

export const THIN_STORY_MAX_STRONG_FACTS = 6;
export const RICH_STORY_MIN_STRONG_FACTS = 16;
const MIN_BEATS = 8;

export type LengthPlan = {
  band: "thin" | "normal" | "rich";
  minSec: number;
  maxSec: number;
  strongFacts: number;
};

/** Strong = high confidence and not mere context. */
export function planLength(factSheet: FactSheet, options: ScriptOptions): LengthPlan {
  const strongFacts = factSheet.facts.filter(
    (fact) => fact.confidence === "high" && fact.type !== "context",
  ).length;
  const [band, lo, hi]: [LengthPlan["band"], number, number] =
    strongFacts <= THIN_STORY_MAX_STRONG_FACTS
      ? ["thin", 60, 75]
      : strongFacts >= RICH_STORY_MIN_STRONG_FACTS
        ? ["rich", 120, 140]
        : ["normal", 90, 120];
  const maxSec = Math.min(hi, options.maxSec);
  const minSec = Math.min(Math.max(lo, options.minSec), maxSec);
  return { band, minSec, maxSec, strongFacts };
}

function firstWords(text: string, count: number): string {
  return text.trim().split(/\s+/).slice(0, count).join(" ");
}

/**
 * Deterministic post-processing: clean fields, drop unknown fact ids, time the
 * beats, and trim optional beats (from the end) past the soft limit.
 */
export function finaliseScript(
  draft: ScriptDraft,
  factSheet: FactSheet,
  options: ScriptOptions,
  plan: LengthPlan,
): ScriptOutput {
  const wps = wordsPerSecond(options.language, options.pace);
  const knownFacts = new Set(factSheet.facts.map((fact) => fact.id));

  let beats: Omit<Beat, "index" | "startSec" | "endSec">[] = draft.beats
    .filter((beat) => beat.spokenText.trim())
    .map((beat) => {
      const factIds = [...new Set(beat.factIds)].filter((id) => knownFacts.has(id));
      const onScreen = beat.onScreenText?.trim();
      return {
        spokenText: beat.spokenText.trim(),
        ...(onScreen ? { onScreenText: firstWords(onScreen, 6) } : {}),
        kind: beat.kind === "fact" && factIds.length > 0 ? "fact" : "explain",
        factIds,
        priority: beat.priority,
        ...(beat.cutNote?.trim() ? { cutNote: beat.cutNote.trim() } : {}),
      };
    });

  const limitWords = options.maxSec * (1 + MAX_SEC_TOLERANCE) * wps;
  const trimmed: string[] = [];
  while (totalWords(beats) > limitWords && beats.length > MIN_BEATS) {
    // Never cut the hook (first) or CTA (last).
    let cut = -1;
    for (let i = beats.length - 2; i >= 1; i -= 1) {
      if (beats[i].priority === "optional") {
        cut = i;
        break;
      }
    }
    if (cut < 0) {
      break;
    }
    trimmed.push(beats[cut].spokenText);
    beats = beats.filter((_, i) => i !== cut);
  }

  const timed = timeBeats(beats, wps);
  const wordCount = totalWords(beats);
  const estimatedSec = Math.round(wordCount / wps);

  const reasonParts = [
    `${plan.band} story (${plan.strongFacts} strong facts) → target ${plan.minSec}–${plan.maxSec}s`,
    `${wordCount} words at ${wps} words/sec ≈ ${estimatedSec}s`,
  ];
  if (trimmed.length > 0) {
    reasonParts.push(`${trimmed.length} optional beat(s) dropped to stay near the ${options.maxSec}s limit`);
  }
  if (estimatedSec > options.maxSec * (1 + MAX_SEC_TOLERANCE)) {
    reasonParts.push(`still over the ${options.maxSec}s soft limit; cut optional beats while editing`);
  }
  const hookSec = (timed[0]?.endSec ?? 0) - (timed[0]?.startSec ?? 0);
  if (hookSec > HOOK_MAX_SEC) {
    reasonParts.push(`hook runs ${hookSec}s (> ${HOOK_MAX_SEC}s); consider a shorter hook option`);
  }

  const cta = draft.cta.trim() || timed.at(-1)?.spokenText || "";
  return {
    title: draft.title.trim(),
    hookOptions: draft.hookOptions.map((hook) => hook.trim()),
    beats: timed,
    cta,
    wordCount,
    estimatedSec,
    lengthReason: reasonParts.join("; "),
    wordsPerSecond: wps,
    ...(factSheet.isFinance ? { disclaimer: FINANCE_DISCLAIMER } : {}),
  };
}

export type ScriptWriterDeps = { generate?: VideoGenerate; model?: string };

export function createScriptWriter(deps: ScriptWriterDeps = {}) {
  const generate = deps.generate ?? defaultVideoGenerate;

  return async function scriptWriter(
    rawInput: ScriptWriterInput,
  ): Promise<AgentResult<ScriptOutput>> {
    return runVideoAgent(
      "scriptWriter",
      { input: scriptWriterInputSchema, output: scriptOutputSchema },
      rawInput,
      async ({ factSheet, story, options }) => {
        const plan = planLength(factSheet, options);
        const wps = wordsPerSecond(options.language, options.pace);

        const draft = await generate({
          model: resolveVideoModel(deps.model),
          system: buildScriptWriterSystemPrompt({
            language: options.language,
            targetWordsMin: Math.round(plan.minSec * wps),
            targetWordsMax: Math.round(plan.maxSec * wps),
            hookMaxWords: Math.floor(HOOK_MAX_SEC * wps),
            ctaMaxWords: Math.floor(CTA_MAX_SEC * wps),
            isFinance: factSheet.isFinance,
          }),
          prompt: `Write the video script for: ${story.title}`,
          extraContext: {
            category: story.category,
            aspectRatio: options.aspectRatio,
            factSheet: {
              facts: factSheet.facts.map(({ id, text, type, value, speaker, confidence }) => ({
                id,
                text,
                type,
                value: value ?? null,
                speaker: speaker ?? null,
                confidence,
              })),
              whatHappened: factSheet.whatHappened,
              whatChanged: factSheet.whatChanged,
              whyItMatters: factSheet.whyItMatters,
              whoIsAffected: factSheet.whoIsAffected,
              openQuestions: factSheet.openQuestions,
              conflicts: factSheet.conflicts,
            },
          },
          schemaName: "VideoScriptDraft",
          schemaDescription: "Talking-head video script beats grounded in the fact sheet.",
          output: scriptDraftSchema,
          temperature: 0.4,
          maxOutputTokens: 6_000,
        });

        return finaliseScript(draft, factSheet, options, plan);
      },
    );
  };
}

export const runScriptWriter = createScriptWriter();

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { FactSheet } from "@/Agents/video/researchBuilder/schema";
import type { VideoGenerate } from "@/Agents/video/shared/llm";
import { createScriptWriter, planLength, type ScriptDraft, type ScriptOptions } from "./index";

function factSheet(strongFacts: number, isFinance = false): FactSheet {
  return {
    facts: Array.from({ length: strongFacts }, (_, i) => ({
      id: `F${i + 1}`,
      text: `Fact ${i + 1}`,
      type: "event" as const,
      sourceIds: ["s1"],
      sourceUrls: ["https://a.example"],
      confidence: "high" as const,
    })),
    whatHappened: "x",
    whatChanged: "",
    whyItMatters: [],
    whoIsAffected: [],
    openQuestions: [],
    conflicts: [],
    isFinance,
    sources: [],
    searchQueries: [],
  };
}

const options: ScriptOptions = { language: "en", minSec: 60, maxSec: 140, pace: "normal", aspectRatio: "9:16" };
const words = (n: number) => Array.from({ length: n }, () => "word").join(" ");

function draft(beatWords: number[], optional: number[] = []): ScriptDraft {
  return {
    title: "T",
    hookOptions: ["a", "b", "c"],
    beats: beatWords.map((n, i) => ({
      spokenText: words(n),
      onScreenText: i === 1 ? "one two three four five six seven" : null,
      kind: "fact",
      factIds: i === 1 ? ["F1", "F999"] : [],
      priority: optional.includes(i) ? "optional" : "core",
      cutNote: null,
    })),
    cta: "Follow for more",
  };
}

const gen = (output: unknown): VideoGenerate => (async () => output) as unknown as VideoGenerate;

describe("planLength", () => {
  it("bands by strong fact count and clamps to maxSec", () => {
    assert.deepEqual(planLength(factSheet(4), options), { band: "thin", minSec: 60, maxSec: 75, strongFacts: 4 });
    assert.equal(planLength(factSheet(10), options).band, "normal");
    assert.deepEqual(planLength(factSheet(20), options), { band: "rich", minSec: 120, maxSec: 140, strongFacts: 20 });
    assert.deepEqual(planLength(factSheet(20), { ...options, maxSec: 90 }), { band: "rich", minSec: 90, maxSec: 90, strongFacts: 20 });
  });
});

describe("scriptWriter", () => {
  it("times beats from cumulative words and cleans fields", async () => {
    const run = createScriptWriter({ generate: gen(draft([12, 24, 24, 24, 24, 24, 24, 12])) });
    const result = await run({ factSheet: factSheet(4), story: { title: "S", category: "Tech" }, options });
    assert.equal(result.status, "ok");
    if (result.status !== "ok") return;
    const { beats } = result.data;
    assert.deepEqual([beats[0].startSec, beats[0].endSec, beats[1].endSec], [0, 5, 15]);
    assert.equal(result.data.wordCount, 168);
    assert.equal(result.data.estimatedSec, 70);
    assert.equal(beats[1].onScreenText, "one two three four five six");
    assert.deepEqual(beats[1].factIds, ["F1"]);
    assert.equal(beats[0].kind, "explain", "fact beat without known facts becomes explain");
    assert.match(result.data.lengthReason, /thin story/);
    assert.equal(result.data.disclaimer, undefined);
  });

  it("drops optional beats (not hook/CTA) past the soft limit", async () => {
    // 10 beats × 40 words = 400 words ≈ 167s at 2.4 wps; limit 140 × 1.1 × 2.4 ≈ 370 words.
    const run = createScriptWriter({ generate: gen(draft(Array(10).fill(40), [0, 3, 8, 9])) });
    const result = await run({ factSheet: factSheet(20, true), story: { title: "S", category: "Markets" }, options });
    assert.equal(result.status, "ok");
    if (result.status !== "ok") return;
    assert.equal(result.data.beats.length, 9);
    assert.equal(result.data.wordCount, 360);
    assert.deepEqual(result.data.beats.map((b) => b.index), [0, 1, 2, 3, 4, 5, 6, 7, 8]);
    assert.equal(result.data.beats[0].priority, "optional", "hook kept even if optional");
    assert.equal(result.data.beats.at(-1)?.priority, "optional", "CTA kept even if optional");
    assert.equal(result.data.disclaimer, "For information only, not investment advice.");
  });

  it("uses Hindi speaking rates", async () => {
    const run = createScriptWriter({ generate: gen(draft(Array(8).fill(22))) });
    const result = await run({ factSheet: factSheet(4), story: { title: "S", category: "x" }, options: { ...options, language: "hi" } });
    assert.equal(result.status === "ok" && result.data.estimatedSec, 80);
  });

  it("fails without throwing on a bad draft", async () => {
    const run = createScriptWriter({ generate: gen({ ...draft([10]), hookOptions: ["only one"] }) });
    const result = await run({ factSheet: factSheet(4), story: { title: "S", category: "x" }, options });
    assert.equal(result.status, "failed");
  });
});

import { factSheetSchema } from "@/Agents/video/researchBuilder/schema";
import { scriptOutputSchema } from "@/Agents/video/scriptWriter/schema";
import { z } from "zod";

export const factCheckerInputSchema = z.object({
  factSheet: factSheetSchema,
  script: scriptOutputSchema,
  storyTitle: z.string(),
  language: z.enum(["hi", "en"]),
});

export type FactCheckerInput = z.input<typeof factCheckerInputSchema>;

export const beatCheckSchema = z.object({
  /** Index in the final script. */
  index: z.number().int().min(0),
  status: z.enum(["ok", "fixed", "removed_claim"]),
  issues: z.array(z.string()),
});

export const factCheckSchema = z.object({
  beats: z.array(beatCheckSchema),
  /** Beats removed entirely because nothing supported was left. */
  removedBeats: z.array(
    z.object({ originalIndex: z.number().int(), spokenText: z.string(), issues: z.array(z.string()) }),
  ),
  passed: z.boolean(),
});

export const factCheckerOutputSchema = z.object({
  factCheck: factCheckSchema,
  script: scriptOutputSchema,
});

export type BeatCheck = z.infer<typeof beatCheckSchema>;
export type FactCheck = z.infer<typeof factCheckSchema>;
export type FactCheckerOutput = z.infer<typeof factCheckerOutputSchema>;

/** LLM audit output. `span` is the exact offending text copied from the beat. */
export const auditSchema = z.object({
  beats: z.array(
    z.object({
      index: z.number().int(),
      issues: z.array(z.object({ span: z.string(), problem: z.string() })),
    }),
  ),
});

export type Audit = z.infer<typeof auditSchema>;

export const rewriteSchema = z.object({
  beats: z.array(
    z.object({
      index: z.number().int(),
      spokenText: z.string(),
      onScreenText: z.string().nullable(),
    }),
  ),
});

export type Rewrite = z.infer<typeof rewriteSchema>;

/**
 * factChecker — every number, date, name and quote in the script must match
 * the FactSheet.
 *
 * 1. Check: deterministic number match (₹1,200 cr = 1200 crore) + LLM audit for
 *    names / dates / quotes / unsupported events.
 * 2. Failing beats are rewritten once from FactSheet facts only, then re-checked.
 * 3. Still failing → the offending sentences are removed (whole beat if nothing
 *    is left). Facts are never added. Beats are re-timed afterwards.
 */

import { runVideoAgent, type AgentResult } from "@/Agents/video/shared/agentResult";
import {
  defaultVideoGenerate,
  resolveVideoModel,
  type VideoGenerate,
} from "@/Agents/video/shared/llm";
import {
  extractNumbers,
  splitSentences,
  unsupportedNumbers,
  type NumberToken,
} from "@/Agents/video/shared/numbers";
import { timeBeats, totalWords } from "@/Agents/video/shared/timing";
import type { FactSheet } from "@/Agents/video/researchBuilder/schema";
import type { Beat, ScriptOutput } from "@/Agents/video/scriptWriter/schema";
import { AUDIT_SYSTEM_PROMPT, buildRewriteSystemPrompt, PROMPT_VERSION } from "./prompt";
import {
  auditSchema,
  factCheckerInputSchema,
  factCheckerOutputSchema,
  rewriteSchema,
  type BeatCheck,
  type FactCheckerInput,
  type FactCheckerOutput,
} from "./schema";

export { PROMPT_VERSION };
export * from "./schema";

export function factSheetNumbers(factSheet: FactSheet): NumberToken[] {
  return factSheet.facts.flatMap((fact) =>
    extractNumbers(`${fact.text} ${fact.value ?? ""}`),
  );
}

type Issue = { span: string | null; problem: string };
type WorkingBeat = Beat & { originalIndex: number };

function numberIssues(beat: Pick<Beat, "spokenText" | "onScreenText">, allowed: NumberToken[]): Issue[] {
  return unsupportedNumbers(`${beat.spokenText}\n${beat.onScreenText ?? ""}`, allowed).map(
    (token) => ({ span: token.raw, problem: `number "${token.raw}" is not in the fact sheet` }),
  );
}

function factsForPrompt(factSheet: FactSheet) {
  return factSheet.facts.map(({ id, text, type, value, speaker }) => ({
    id,
    text,
    type,
    value: value ?? null,
    speaker: speaker ?? null,
  }));
}

/** Removes sentences containing an issue span; `null` span → drop the whole text. */
function removeClaims(text: string, issues: Issue[]): string {
  if (issues.some((issue) => !issue.span)) {
    return "";
  }
  const spans = issues.map((issue) => issue.span!.toLowerCase());
  return splitSentences(text)
    .filter((sentence) => {
      const lower = sentence.toLowerCase();
      return !spans.some((span) => lower.includes(span));
    })
    .join(" ");
}

export type FactCheckerDeps = { generate?: VideoGenerate; model?: string };

export function createFactChecker(deps: FactCheckerDeps = {}) {
  const generate = deps.generate ?? defaultVideoGenerate;

  return async function factChecker(
    rawInput: FactCheckerInput,
  ): Promise<AgentResult<FactCheckerOutput>> {
    return runVideoAgent(
      "factChecker",
      { input: factCheckerInputSchema, output: factCheckerOutputSchema },
      rawInput,
      async ({ factSheet, script, storyTitle, language }) => {
        const model = resolveVideoModel(deps.model);
        const allowed = factSheetNumbers(factSheet);
        const facts = factsForPrompt(factSheet);

        async function audit(beats: WorkingBeat[]): Promise<Map<number, Issue[]>> {
          const issues = new Map<number, Issue[]>(
            beats.map((beat) => [beat.originalIndex, numberIssues(beat, allowed)]),
          );
          if (beats.length === 0) {
            return issues;
          }
          const result = await generate({
            model,
            system: AUDIT_SYSTEM_PROMPT,
            prompt: "Check these script beats against the fact sheet.",
            extraContext: {
              facts,
              conflicts: factSheet.conflicts,
              beats: beats.map((beat) => ({
                index: beat.originalIndex,
                spokenText: beat.spokenText,
                onScreenText: beat.onScreenText ?? null,
              })),
            },
            schemaName: "VideoScriptAudit",
            schemaDescription: "Unsupported claims per beat.",
            output: auditSchema,
            temperature: 0,
            maxOutputTokens: 4_000,
          });
          for (const row of result.beats) {
            const list = issues.get(row.index);
            if (!list) {
              continue;
            }
            for (const issue of row.issues) {
              const span = issue.span.trim();
              list.push({ span: span || null, problem: issue.problem.trim() });
            }
          }
          return issues;
        }

        const working: WorkingBeat[] = script.beats.map((beat) => ({ ...beat, originalIndex: beat.index }));
        const firstIssues = await audit(working);
        const failing = working.filter((beat) => (firstIssues.get(beat.originalIndex) ?? []).length > 0);

        // One rewrite pass for failing beats.
        const rewritten = new Map<number, WorkingBeat>();
        if (failing.length > 0) {
          const rewrite = await generate({
            model,
            system: buildRewriteSystemPrompt(language),
            prompt: "Rewrite these beats so they only use facts from the fact sheet.",
            extraContext: {
              facts,
              beats: failing.map((beat) => ({
                index: beat.originalIndex,
                spokenText: beat.spokenText,
                onScreenText: beat.onScreenText ?? null,
                issues: (firstIssues.get(beat.originalIndex) ?? []).map((issue) => issue.problem),
              })),
            },
            schemaName: "VideoScriptRewrite",
            schemaDescription: "Rewritten beats using only fact-sheet facts.",
            output: rewriteSchema,
            temperature: 0,
            maxOutputTokens: 4_000,
          });
          for (const row of rewrite.beats) {
            const original = failing.find((beat) => beat.originalIndex === row.index);
            if (!original || !row.spokenText.trim()) {
              continue;
            }
            const onScreen = row.onScreenText?.trim();
            rewritten.set(row.index, {
              ...original,
              spokenText: row.spokenText.trim(),
              onScreenText: onScreen ? onScreen.split(/\s+/).slice(0, 6).join(" ") : undefined,
            });
          }
        }

        const recheck = await audit([...rewritten.values()]);

        const finalBeats: WorkingBeat[] = [];
        const checks: Array<Omit<BeatCheck, "index"> & { originalIndex: number }> = [];
        const removedBeats: FactCheckerOutput["factCheck"]["removedBeats"] = [];

        for (const beat of working) {
          const initial = firstIssues.get(beat.originalIndex) ?? [];
          if (initial.length === 0) {
            finalBeats.push(beat);
            checks.push({ originalIndex: beat.originalIndex, status: "ok", issues: [] });
            continue;
          }
          const candidate = rewritten.get(beat.originalIndex);
          const remaining = candidate ? (recheck.get(beat.originalIndex) ?? []) : initial;
          const problems = initial.map((issue) => issue.problem);
          if (candidate && remaining.length === 0) {
            finalBeats.push(candidate);
            checks.push({ originalIndex: beat.originalIndex, status: "fixed", issues: problems });
            continue;
          }

          const base = candidate ?? beat;
          const spokenText = removeClaims(base.spokenText, remaining);
          const onScreenIssues = numberIssues({ spokenText: "", onScreenText: base.onScreenText }, allowed);
          const allIssues = [...problems, ...remaining.map((issue) => issue.problem)];
          // Removal must leave nothing unsupported; otherwise drop the beat.
          if (!spokenText || numberIssues({ spokenText }, allowed).length > 0) {
            removedBeats.push({ originalIndex: beat.originalIndex, spokenText: beat.spokenText, issues: allIssues });
            continue;
          }
          finalBeats.push({
            ...base,
            spokenText,
            onScreenText: onScreenIssues.length > 0 ? undefined : base.onScreenText,
          });
          checks.push({ originalIndex: beat.originalIndex, status: "removed_claim", issues: allIssues });
        }

        const timed = timeBeats(
          finalBeats.map(({ originalIndex: _o, ...beat }) => beat),
          script.wordsPerSecond,
        );
        const indexByOriginal = new Map(finalBeats.map((beat, i) => [beat.originalIndex, i]));
        const wordCount = totalWords(timed);
        const estimatedSec = Math.round(wordCount / script.wordsPerSecond);

        const hook = timed[0]?.spokenText ?? "";
        const supported = (text: string) => unsupportedNumbers(text, allowed).length === 0;
        const changed = checks.some((check) => check.status !== "ok") || removedBeats.length > 0;

        const finalScript: ScriptOutput = {
          ...script,
          title: supported(script.title) ? script.title : storyTitle,
          hookOptions: script.hookOptions.map((option) => (supported(option) ? option : hook)),
          beats: timed,
          cta: timed.at(-1)?.spokenText ?? script.cta,
          wordCount,
          estimatedSec,
          lengthReason: changed
            ? `${script.lengthReason}; after fact check ${wordCount} words ≈ ${estimatedSec}s`
            : script.lengthReason,
        };

        const passed =
          timed.length > 0 &&
          timed.every((beat) => numberIssues(beat, allowed).length === 0) &&
          supported(finalScript.title) &&
          finalScript.hookOptions.every(supported);

        return {
          factCheck: {
            beats: checks.map(({ originalIndex, ...check }) => ({
              index: indexByOriginal.get(originalIndex)!,
              ...check,
            })),
            removedBeats,
            passed,
          },
          script: finalScript,
        };
      },
    );
  };
}

export const runFactChecker = createFactChecker();

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { FactSheet } from "@/Agents/video/researchBuilder/schema";
import type { ScriptOutput } from "@/Agents/video/scriptWriter/schema";
import type { VideoGenerate } from "@/Agents/video/shared/llm";
import { extractNumbers, numbersMatch } from "@/Agents/video/shared/numbers";
import { createFactChecker, factSheetNumbers } from "./index";

const factSheet: FactSheet = {
  facts: [
    { id: "F1", text: "Acme raised ₹1,200 crore", type: "number", value: "₹1,200 crore", sourceIds: ["s1"], sourceUrls: [], confidence: "high" },
    { id: "F2", text: "Jane Roe is the CEO of Acme", type: "name", sourceIds: ["s1"], sourceUrls: [], confidence: "high" },
    { id: "F3", text: "The round closed in 2026", type: "date", value: "2026", sourceIds: ["s1"], sourceUrls: [], confidence: "high" },
  ],
  whatHappened: "Acme raised money.",
  whatChanged: "",
  whyItMatters: [],
  whoIsAffected: [],
  openQuestions: [],
  conflicts: [],
  isFinance: false,
  sources: [],
  searchQueries: [],
};

const texts = [
  "Acme just raised 1200 cr.",
  "It will hire 900 people. Jane Roe leads it.",
  "Shares jumped 20% today.",
  "John Doe agreed. Acme confirmed the round.",
  "That happened in 2026.",
  "Here's why it matters.",
  "Watch what Acme does next.",
  "Follow for more.",
];

const script: ScriptOutput = {
  title: "Acme's 50x moment",
  hookOptions: ["Acme raised ₹1,200 crore", "Is this 2026's biggest round?", "Why 7 investors said yes"],
  beats: texts.map((spokenText, index) => ({
    index,
    startSec: index * 2,
    endSec: index * 2 + 2,
    spokenText,
    kind: "explain" as const,
    factIds: [],
    priority: "core" as const,
  })),
  cta: "Follow for more.",
  wordCount: 40,
  estimatedSec: 17,
  lengthReason: "thin",
  wordsPerSecond: 2.4,
};

type Ctx = { beats: Array<{ index: number; spokenText: string }> };

const fakeGenerate = (async (params: { schemaName?: string; extraContext?: unknown }) => {
  const ctx = params.extraContext as Ctx;
  if (params.schemaName === "VideoScriptAudit") {
    return {
      beats: ctx.beats.map((beat) => ({
        index: beat.index,
        issues: beat.spokenText.includes("John Doe")
          ? [{ span: "John Doe", problem: "John Doe is not in the fact sheet" }]
          : [],
      })),
    };
  }
  // Rewrite: fixes beat 1, makes beat 2 worse, skips beat 3.
  return {
    beats: ctx.beats.flatMap((beat) =>
      beat.index === 1
        ? [{ index: 1, spokenText: "Jane Roe leads Acme.", onScreenText: null }]
        : beat.index === 2
          ? [{ index: 2, spokenText: "Shares jumped 25%.", onScreenText: null }]
          : [],
    ),
  };
}) as unknown as VideoGenerate;

describe("factChecker", () => {
  it("fixes, removes claims and drops unsupported beats", async () => {
    const run = createFactChecker({ generate: fakeGenerate });
    const result = await run({ factSheet, script, storyTitle: "Acme funding", language: "en" });
    assert.equal(result.status, "ok");
    if (result.status !== "ok") return;
    const { factCheck, script: out } = result.data;

    assert.deepEqual(
      factCheck.beats.map((b) => [b.index, b.status]),
      [[0, "ok"], [1, "fixed"], [2, "removed_claim"], [3, "ok"], [4, "ok"], [5, "ok"], [6, "ok"]],
    );
    assert.deepEqual(factCheck.removedBeats.map((b) => b.originalIndex), [2]);
    assert.equal(out.beats[1].spokenText, "Jane Roe leads Acme.");
    assert.equal(out.beats[2].spokenText, "Acme confirmed the round.");
    assert.equal(out.beats.length, 7);
    assert.deepEqual(out.beats.map((b) => b.index), [0, 1, 2, 3, 4, 5, 6]);
    assert.equal(out.title, "Acme funding", "title with unsupported number falls back");
    assert.equal(out.hookOptions[2], out.beats[0].spokenText);
    assert.equal(factCheck.passed, true);
  });

  it("every number in the final script exists in the FactSheet", async () => {
    const run = createFactChecker({ generate: fakeGenerate });
    const result = await run({ factSheet, script, storyTitle: "Acme funding", language: "en" });
    assert.equal(result.status, "ok");
    if (result.status !== "ok") return;
    const allowed = factSheetNumbers(factSheet);
    const out = result.data.script;
    const scriptText = [
      out.title,
      ...out.hookOptions,
      out.cta,
      ...out.beats.flatMap((b) => [b.spokenText, b.onScreenText ?? ""]),
    ].join("\n");
    const numbers = extractNumbers(scriptText);
    assert.ok(numbers.length > 0);
    for (const token of numbers) {
      assert.ok(
        allowed.some((fact) => numbersMatch(token, fact)),
        `"${token.raw}" is not in the FactSheet`,
      );
    }
  });

  it("returns failed when the model errors", async () => {
    const run = createFactChecker({
      generate: (async () => {
        throw new Error("timeout");
      }) as unknown as VideoGenerate,
    });
    const result = await run({ factSheet, script, storyTitle: "x", language: "en" });
    assert.equal(result.status, "failed");
  });
});

