import { creativeDirectionSchema } from "@/Agents/video/creativeDirector/schema";
import { factSheetSchema } from "@/Agents/video/researchBuilder/schema";
import { scriptOutputSchema } from "@/Agents/video/scriptWriter/schema";
import { z } from "zod";

export const publishingKitInputSchema = z.object({
  script: scriptOutputSchema,
  factSheet: factSheetSchema,
  direction: creativeDirectionSchema,
  language: z.enum(["hi", "en"]),
  aspectRatio: z.enum(["9:16", "16:9"]),
});

export type PublishingKitInput = z.input<typeof publishingKitInputSchema>;

export const TITLE_STYLES = ["curiosity", "direct", "number", "question", "hindi_english_mix"] as const;

/** OpenAI image sizes (custom WIDTHxHEIGHT, multiples of 16) matching the video. */
export const THUMBNAIL_SIZE = { "16:9": "1536x864", "9:16": "864x1536" } as const;

export const publishingKitSchema = z.object({
  titles: z
    .array(z.object({ text: z.string().min(1), style: z.enum(TITLE_STYLES), charCount: z.number().int() }))
    .min(1)
    .max(5),
  thumbnail: z.object({
    concepts: z
      .array(z.object({ idea: z.string(), textOverlay: z.string(), layout: z.string() }))
      .min(1)
      .max(3),
    openaiPrompts: z
      .array(z.object({ prompt: z.string().min(1), size: z.string(), notes: z.string() }))
      .max(3),
    tips: z.array(z.string()),
  }),
  descriptions: z.object({
    youtube: z.string().min(1),
    shorts: z.string().min(1),
    instagram: z.string().min(1),
    /** ≤ 280 chars. */
    x: z.string().min(1).max(280),
  }),
  hashtags: z.array(z.string()).max(10),
  pinnedComment: z.string().min(1),
  /** Items dropped for claiming what the script does not say, or unsafe prompts. */
  dropped: z.array(z.string()),
});

export type PublishingKit = z.infer<typeof publishingKitSchema>;

/** LLM output (strict-mode friendly). */
export const publishingDraftSchema = z.object({
  titles: z.array(z.object({ text: z.string(), style: z.enum(TITLE_STYLES) })).min(5).max(5),
  thumbnail: z.object({
    concepts: z
      .array(z.object({ idea: z.string(), textOverlay: z.string(), layout: z.string() }))
      .min(3)
      .max(3),
    openaiPrompts: z.array(z.object({ prompt: z.string(), notes: z.string() })).min(2).max(3),
    tips: z.array(z.string()).max(5),
  }),
  descriptions: z.object({
    youtubeSummary: z.string(),
    youtubeKeyPoints: z.array(z.string()).max(6),
    shorts: z.string(),
    instagram: z.string(),
    x: z.string(),
  }),
  hashtags: z.array(z.string()).max(12),
  pinnedComment: z.string(),
});

export type PublishingDraft = z.infer<typeof publishingDraftSchema>;

/** Bump whenever the system prompt below changes. */
export const PROMPT_VERSION = "v1";

export function buildPublishingKitSystemPrompt(input: {
  language: "hi" | "en";
  aspectRatio: "9:16" | "16:9";
  isFinance: boolean;
}): string {
  return [
    "You write the publishing kit for a talking-head news video: titles, thumbnail ideas, descriptions, hashtags, pinned comment.",
    input.language === "hi"
      ? "The video is in Hindi: write titles and descriptions in Hindi (Devanagari) or natural Hinglish; include one hindi_english_mix title."
      : "The video is in English: write in English; a hindi_english_mix title is optional.",
    "",
    "TRUTH: Use only what the final script says. Titles, thumbnail text and descriptions must not claim, imply or exaggerate",
    "anything beyond the script — no numbers, names or outcomes the script does not contain. No clickbait lies, no investment advice.",
    input.isFinance ? "Finance story: neutral, informational tone." : "",
    "",
    "titles: exactly 5, ideally ≤ 70 characters, one per style: curiosity, direct, number, question, and hindi_english_mix",
    "(or a second direct/curiosity title for English if a mix feels forced — still label it hindi_english_mix only if it mixes).",
    "",
    "thumbnail.concepts: 3, each with idea, textOverlay (≤ 4 words, from the script), and layout (where the creator's face",
    "from a video frame goes, where the text goes).",
    `thumbnail.openaiPrompts: 2–3 image prompts for the BACKGROUND/SCENE only (${input.aspectRatio}), leaving clear empty space`,
    "for the creator's face cut-out and the text overlay. No people, no real logos or brands, no text, no fake documents or headlines.",
    "thumbnail.tips: short practical tips (contrast, face expression, text size).",
    "",
    "descriptions: youtubeSummary (2–3 sentences), youtubeKeyPoints (3–6 bullets, from the script), shorts (≤ 2 short lines),",
    "instagram (caption, 3–5 short lines, may include emojis), x (≤ 240 characters, no hashtags).",
    "Do not write sources, chapters or disclaimers — they are added automatically.",
    "hashtags: 5–10, relevant, no spaces. pinnedComment: a question that invites discussion, grounded in the script.",
  ]
    .filter(Boolean)
    .join("\n");
}

/**
 * publishingKit — titles, thumbnail concepts + background prompts, platform
 * descriptions, hashtags and a pinned comment.
 *
 * Guards: titles / thumbnail text may only use numbers and quoted words that
 * the final script contains; thumbnail prompts pass the genPrompter safety
 * guard. The YouTube description's Sources (FactSheet URLs), Chapters
 * placeholder and finance disclaimer are added deterministically.
 */

import { runVideoAgent, type AgentResult } from "@/Agents/video/shared/agentResult";
import {
  defaultVideoGenerate,
  resolveVideoModel,
  type VideoGenerate,
} from "@/Agents/video/shared/llm";
import {
  extractNumbers,
  extractQuotedSpans,
  normaliseQuoteText,
  unsupportedNumbers,
} from "@/Agents/video/shared/numbers";
import { blockedNames, isSafePrompt } from "@/Agents/video/genPrompter";
import { FINANCE_DISCLAIMER, type ScriptOutput } from "@/Agents/video/scriptWriter/schema";
import type { FactSheet } from "@/Agents/video/researchBuilder/schema";
import { buildPublishingKitSystemPrompt, PROMPT_VERSION } from "./prompt";
import {
  publishingDraftSchema,
  publishingKitInputSchema,
  publishingKitSchema,
  THUMBNAIL_SIZE,
  type PublishingDraft,
  type PublishingKit,
  type PublishingKitInput,
} from "./schema";

export { PROMPT_VERSION };
export * from "./schema";

export const X_MAX_CHARS = 280;
export const CHAPTERS_PLACEHOLDER = "Chapters:\n0:00 (filled in after editing)";

function scriptText(script: ScriptOutput): string {
  return [script.title, ...script.hookOptions, ...script.beats.flatMap((b) => [b.spokenText, b.onScreenText ?? ""])].join("\n");
}

/** Numbers and quoted words must already be in the script. */
export function claimsOnlyScript(text: string, script: ScriptOutput): boolean {
  const body = scriptText(script);
  if (unsupportedNumbers(text, extractNumbers(body)).length > 0) {
    return false;
  }
  const normalisedBody = normaliseQuoteText(body);
  return extractQuotedSpans(text).every((span) => normalisedBody.includes(normaliseQuoteText(span)));
}

export function truncateAtWord(text: string, max: number): string {
  if (text.length <= max) {
    return text;
  }
  const cut = text.slice(0, max - 1);
  const lastSpace = cut.lastIndexOf(" ");
  return `${(lastSpace > max * 0.6 ? cut.slice(0, lastSpace) : cut).trimEnd()}…`;
}

function normaliseHashtag(tag: string): string | null {
  const body = tag.trim().replace(/^#+/, "").replace(/[\s#]+/g, "");
  return body ? `#${body}` : null;
}

function sourceUrls(factSheet: FactSheet): string[] {
  return [...new Set(factSheet.sources.filter((s) => s.origin !== "story").map((s) => s.url))];
}

export function buildYoutubeDescription(draft: PublishingDraft, factSheet: FactSheet): string {
  const parts = [draft.descriptions.youtubeSummary.trim()];
  const points = draft.descriptions.youtubeKeyPoints.map((p) => p.trim()).filter(Boolean);
  if (points.length > 0) {
    parts.push(`Key points:\n${points.map((p) => `• ${p}`).join("\n")}`);
  }
  const urls = sourceUrls(factSheet);
  if (urls.length > 0) {
    parts.push(`Sources:\n${urls.join("\n")}`);
  }
  parts.push(CHAPTERS_PLACEHOLDER);
  if (factSheet.isFinance) {
    parts.push(FINANCE_DISCLAIMER);
  }
  return parts.join("\n\n");
}

export function finalisePublishingKit(
  draft: PublishingDraft,
  input: { script: ScriptOutput; factSheet: FactSheet; aspectRatio: "9:16" | "16:9" },
): PublishingKit {
  const { script, factSheet } = input;
  const dropped: string[] = [];

  const titles = draft.titles
    .map((t) => ({ text: t.text.trim(), style: t.style }))
    .filter((t) => {
      const ok = Boolean(t.text) && claimsOnlyScript(t.text, script);
      if (!ok && t.text) dropped.push(`title: ${t.text}`);
      return ok;
    })
    .map((t) => ({ ...t, charCount: [...t.text].length }));
  if (titles.length === 0) {
    titles.push({ text: script.title, style: "direct", charCount: [...script.title].length });
  }

  const concepts = draft.thumbnail.concepts
    .map((c) => ({
      idea: c.idea.trim(),
      textOverlay: c.textOverlay.trim().split(/\s+/).slice(0, 4).join(" "),
      layout: c.layout.trim(),
    }))
    .filter((c) => {
      const ok = claimsOnlyScript(`${c.idea}\n${c.textOverlay}`, script);
      if (!ok) dropped.push(`thumbnail concept: ${c.textOverlay}`);
      return ok;
    });
  if (concepts.length === 0) {
    concepts.push({
      idea: "Creator's face beside the main subject of the story.",
      textOverlay: script.title.split(/\s+/).slice(0, 4).join(" "),
      layout: "Face on the right third, text on the left.",
    });
  }

  const names = blockedNames(factSheet);
  const openaiPrompts = draft.thumbnail.openaiPrompts
    .map((p) => ({ prompt: p.prompt.trim(), size: THUMBNAIL_SIZE[input.aspectRatio], notes: p.notes.trim() }))
    .filter((p) => {
      const ok = Boolean(p.prompt) && isSafePrompt(p.prompt, names);
      if (!ok && p.prompt) dropped.push(`thumbnail prompt: ${p.prompt}`);
      return ok;
    });

  const disclaimer = factSheet.isFinance ? `\n\n${FINANCE_DISCLAIMER}` : "";
  const xBase = draft.descriptions.x.trim();
  const xWithDisclaimer = factSheet.isFinance ? `${xBase} ${FINANCE_DISCLAIMER}` : xBase;

  const hashtags = [
    ...new Set(draft.hashtags.map(normaliseHashtag).filter((tag): tag is string => tag != null)),
  ].slice(0, 10);

  return {
    titles: titles.slice(0, 5),
    thumbnail: {
      concepts: concepts.slice(0, 3),
      openaiPrompts,
      tips: draft.thumbnail.tips.map((tip) => tip.trim()).filter(Boolean),
    },
    descriptions: {
      youtube: buildYoutubeDescription(draft, factSheet),
      shorts: draft.descriptions.shorts.trim().split(/\n+/).slice(0, 2).join("\n") || script.title,
      instagram: `${draft.descriptions.instagram.trim() || script.title}${disclaimer}`,
      x: truncateAtWord(xWithDisclaimer.length <= X_MAX_CHARS ? xWithDisclaimer : xBase || script.title, X_MAX_CHARS),
    },
    hashtags,
    pinnedComment: draft.pinnedComment.trim() || "What do you think? Tell us in the comments.",
    dropped,
  };
}

export type PublishingKitDeps = { generate?: VideoGenerate; model?: string };

export function createPublishingKit(deps: PublishingKitDeps = {}) {
  const generate = deps.generate ?? defaultVideoGenerate;

  return async function publishingKit(
    rawInput: PublishingKitInput,
  ): Promise<AgentResult<PublishingKit>> {
    return runVideoAgent(
      "publishingKit",
      { input: publishingKitInputSchema, output: publishingKitSchema },
      rawInput,
      async ({ script, factSheet, direction, language, aspectRatio }) => {
        const draft = await generate({
          model: resolveVideoModel(deps.model),
          system: buildPublishingKitSystemPrompt({ language, aspectRatio, isFinance: factSheet.isFinance }),
          prompt: `Write the publishing kit for: ${script.title}`,
          extraContext: {
            script: {
              title: script.title,
              hookOptions: script.hookOptions,
              beats: script.beats.map((beat) => beat.spokenText),
              cta: script.cta,
            },
            look: {
              colorTreatment: direction.global.colorTreatment,
              hookTreatment: direction.global.hookTreatment,
            },
          },
          schemaName: "VideoPublishingKit",
          schemaDescription: "Titles, thumbnail ideas, descriptions, hashtags and pinned comment.",
          output: publishingDraftSchema,
          temperature: 0.6,
          maxOutputTokens: 4_000,
        });
        return finalisePublishingKit(draft, { script, factSheet, aspectRatio });
      },
    );
  };
}

